import "./breadcrumb.css";

import type { ComponentProps } from "react";
import { cx } from "./cx";

export type BreadcrumbProps = ComponentProps<"nav">;
export type BreadcrumbListProps = ComponentProps<"ol">;
export type BreadcrumbItemProps = ComponentProps<"li">;
export type BreadcrumbLinkProps = ComponentProps<"a">;
export type BreadcrumbPageProps = ComponentProps<"span">;

export function Breadcrumb({ className, ...rest }: BreadcrumbProps) {
  return (
    <nav
      aria-label="Breadcrumb"
      className={cx("ns-breadcrumb", className)}
      {...rest}
    />
  );
}

export function BreadcrumbList({ className, ...rest }: BreadcrumbListProps) {
  return <ol className={cx("ns-breadcrumb__list", className)} {...rest} />;
}

export function BreadcrumbItem({
  className,
  children,
  ...rest
}: BreadcrumbItemProps) {
  return (
    <li className={cx("ns-breadcrumb__item", className)} {...rest}>
      {children}
      <span className="ns-breadcrumb__sep" aria-hidden="true">
        /
      </span>
    </li>
  );
}

export function BreadcrumbLink({ className, ...rest }: BreadcrumbLinkProps) {
  return <a className={cx("ns-breadcrumb__link", className)} {...rest} />;
}

export function BreadcrumbPage({ className, ...rest }: BreadcrumbPageProps) {
  return (
    <span
      aria-current="page"
      className={cx("ns-breadcrumb__page", className)}
      {...rest}
    />
  );
}

@layer components {
  .ns-breadcrumb__list {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--space-2, 0.31rem);
    margin: 0;
    padding: 0;
    list-style: none;
    color: var(--text-sub, #767676);
    font-size: var(--type-sm, 0.8rem);
  }

  .ns-breadcrumb__item {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2, 0.31rem);
  }

  .ns-breadcrumb__sep {
    color: var(--text-disabled, var(--text-sub, #767676));
  }

  .ns-breadcrumb__item:last-child .ns-breadcrumb__sep {
    display: none;
  }

  .ns-breadcrumb__link {
    color: inherit;
    text-decoration: none;
  }

  @media (hover: hover) {
    .ns-breadcrumb__link:hover {
      color: var(--text-heading, #111);
    }
  }

  .ns-breadcrumb__page {
    color: var(--text-heading, #111);
  }
}

.ns-breadcrumb a {
  text-decoration: none;
}

a.ns-breadcrumb__link {
  color: var(--text-sub, #767676);
}

@media (hover: hover) {
  a.ns-breadcrumb__link:hover {
    color: var(--text-heading, #111);
  }
}
